const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const intro=document.createElement('div');intro.className='store-intro';intro.innerHTML='<div class="intro-mark"><img src="assets/logo.png" alt="Fragrant Cloud"><span>THE ART OF YOUR SIGNATURE</span><i></i></div><button aria-label="تخطي الافتتاحية">تخطي</button>';document.body.append(intro);
let introEnded=false;function finishIntro(){if(introEnded)return;introEnded=true;intro.classList.add('leaving');document.body.classList.add('store-ready');setTimeout(()=>intro.remove(),1000)}intro.querySelector('button').onclick=finishIntro;setTimeout(finishIntro,reducedMotion?0:2200);
const meter=document.createElement('div');meter.className='motion-meter';meter.setAttribute('aria-hidden','true');document.body.append(meter);
const campaign=document.createElement('section');campaign.className='scroll-campaign';campaign.innerHTML='<div class="campaign-sticky"><img src="assets/collection.png" alt="مجموعة Fragrant Cloud المستوحاة من Mangonificent وCrush on Me وGuilty Elixir" loading="lazy"><div class="campaign-shade"></div><div class="campaign-copy"><span class="eyebrow">FRAGRANT CLOUD — THE SIGNATURE COLLECTION</span><h2>تبدأ الحكاية باختيار.<br><em>وتكتمل بتوقيعك.</em></h2><p>عطور مختلفة. شخصية واحدة: أنت.</p><a class="button gold" href="#catalog">اكتشف المجموعة</a></div><span class="campaign-index">THE COLLECTION / 01</span></div>';$('#story').before(campaign);
const sections=[...document.querySelectorAll('.story,.visit,.branches,.section-head')];sections.forEach(x=>x.classList.add('scroll-reveal'));
let queued=false;function frame(){queued=false;const height=innerHeight;const max=document.documentElement.scrollHeight-height;document.documentElement.style.setProperty('--scroll',max?scrollY/max:0);if(reducedMotion){sections.forEach(x=>x.style.setProperty('--reveal','1'));return}const progress=Math.max(0,Math.min(1,-campaign.getBoundingClientRect().top/(campaign.offsetHeight-height)));campaign.style.setProperty('--progress',progress);const heroProgress=Math.min(1,scrollY/height);$('.hero-art').style.transform=`translateY(${heroProgress*100}px) scale(${1+heroProgress*.08})`;$('.hero-copy').style.transform=`translateY(${heroProgress*-60}px)`;$('.hero-copy').style.opacity=1-heroProgress*.6;sections.forEach(x=>{const y=x.getBoundingClientRect().top;const p=Math.max(0,Math.min(1,(height-y)/(height*.4)));x.style.setProperty('--reveal',p)});const r=$('.editorial').getBoundingClientRect();if(r.bottom>0&&r.top<height)$('.editorial>img').style.transform=`translateY(${(r.top-height*.5)*-.1}px) scale(1.15)`}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(frame)}},{passive:true});addEventListener('resize',frame);frame();
const collectionSection=document.createElement('section');collectionSection.className='collection-stories section';collectionSection.innerHTML='<div class="section-head"><div><span class="eyebrow">EXPLORE THE EDIT</span><h2>عوالم مختلفة.<br><em>اختر ما يشبهك.</em></h2></div><p>اكتشف مجموعاتنا من صورها،<br>ثم تعرّف على كل عطر وأسعاره.</p></div><div class="collection-tiles"><button data-collection="extreme"><img src="assets/extreme.png" alt="مجموعة Extreme" loading="lazy"><span><small>THE EXTREME COLLECTION</small><strong>حضور يلفت الانتباه</strong><b>اكتشف المجموعة</b></span></button><button data-collection="elements"><img src="assets/elements.png" alt="مجموعة Elements" loading="lazy"><span><small>THE ELEMENTS COLLECTION</small><strong>ثلاثة عطور، جوهر واحد</strong><b>اكتشف المجموعة</b></span></button><button data-collection="women"><img src="assets/crystal.png" alt="عطور نسائية — Crystal Noir" loading="lazy"><span><small>THE FEMININE EDIT</small><strong>تفاصيل تعبّر عنكِ</strong><b>اكتشفي العطور</b></span></button></div>';$('#catalog').before(collectionSection);collectionSection.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{const target=document.querySelector('[data-filter="'+b.dataset.collection+'"]');if(target)target.click();$('#catalog').scrollIntoView({behavior:reducedMotion?'instant':'smooth'})});
const backTop=document.createElement('button');backTop.className='back-top';backTop.type='button';backTop.textContent='العودة للأعلى';backTop.setAttribute('aria-label','العودة إلى بداية الصفحة');document.body.append(backTop);backTop.onclick=()=>window.scrollTo({top:0,behavior:reducedMotion?'instant':'smooth'});function toggleBackTop(){backTop.classList.toggle('visible',scrollY>600)}addEventListener('scroll',toggleBackTop,{passive:true});toggleBackTop();
